css:
.d-toolbar-overflow{position:relative;width:280px;max-width:100%;font-family:var(--sans)}
.d-to-bar{display:flex;align-items:center;gap:2px;height:34px;padding:0 2px;border:1px solid var(--line);border-radius:6px;background:var(--paper)}
.d-to-btn{height:24px;min-width:26px;padding:0 6px;border:0;border-radius:2px;background:transparent;color:var(--muted);font:inherit;font-size:var(--fs-11);cursor:pointer}
.d-to-btn:hover{color:var(--ink)}
.d-to-btn[aria-pressed=true]{color:var(--ink);background:var(--bg);box-shadow:inset 0 1px 0 #fff5}
.d-to-btn:focus-visible,.d-to-more:focus-visible,.d-to-item:focus-visible{outline:1px solid var(--ink);outline-offset:1px}
.d-to-more{display:inline-flex;align-items:center;gap:4px;margin-left:auto;height:24px;padding:0 8px;border:1px solid var(--line);border-radius:2px;background:transparent;color:var(--ink);font:inherit;font-size:var(--fs-11);cursor:pointer}
.d-to-more b{font-family:var(--mono);font-weight:400;font-size:var(--fs-9);color:var(--faint)}
.d-to-menu{position:absolute;right:0;top:38px;z-index:2;width:148px;padding:4px;border:1px solid var(--line);border-radius:6px;background:var(--paper);box-shadow:0 12px 24px -8px #20241e26}
.d-to-menu[hidden]{display:none}
.d-to-item{display:block;width:100%;height:28px;padding:0 8px;border:0;border-radius:2px;background:transparent;color:var(--ink);font:inherit;font-size:var(--fs-11);text-align:left;cursor:pointer;opacity:0;transform:translateY(-4px)}
.d-to-item:hover{background:var(--bg)}
.d-toolbar-overflow.is-open .d-to-item{animation:d-toolbar-overflow-item 180ms steps(6) forwards;animation-delay:calc(var(--i,0) * 120ms)}
.d-to-item:nth-child(2){--i:1}
.d-to-item:nth-child(3){--i:2}
@keyframes d-toolbar-overflow-item{to{opacity:1;transform:none}}

init:
root => {
  const box = root.querySelector('.d-toolbar-overflow');
  if (!box || box.dataset.dto) return;
  box.dataset.dto = '1';
  const btn = box.querySelector('.d-to-more');
  const menu = box.querySelector('.d-to-menu');
  const items = [...box.querySelectorAll('.d-to-item')];
  let cur = 0;
  const focusItem = i => { cur = (i + items.length) % items.length; items[cur].focus(); };
  const set = open => {
    box.classList.toggle('is-open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    menu.hidden = !open;
    if (open) setTimeout(() => focusItem(0), 280);
  };
  btn.addEventListener('click', () => set(btn.getAttribute('aria-expanded') !== 'true'));
  items.forEach(it => it.addEventListener('click', () => { set(false); btn.focus(); }));
  box.addEventListener('pointerdown', e => {
    if (!menu.hidden && !menu.contains(e.target) && !btn.contains(e.target)) set(false);
  });
  box.addEventListener('keydown', e => {
    if (e.key === 'Escape') { set(false); btn.focus(); }
    else if (e.key === 'ArrowDown' && !menu.hidden) { e.preventDefault(); focusItem(cur + 1); }
    else if (e.key === 'ArrowUp' && !menu.hidden) { e.preventDefault(); focusItem(cur - 1); }
  });
}
